     "**চৰ্টকাটবোৰ কেৱল তখনই স্বাভাৱিক যেন লাগে যদি আপুনি সেইবোৰ একেলগে ব্যৱহাৰ কৰে।** স্পেচে প্লে আৰু পজ কৰে, এণ্টাৰ (Enter)-এ বৰ্তমানৰ শাৰীটো ষ্টাম্প কৰে, Z-এ এটা শাৰী আনডু কৰে — মাউচ আৰু কীৰ্বোৰ্ডৰ মাজত অহা-যোৱা কৰাৰ পৰিৱৰ্তে প্লেবেকৰ সময়তে পোনপটীয়াকৈ এণ্টাৰ (Enter) হেঁচা মাৰক।",
     "**অডিঅ’ৰ মানদণ্ডে নিখুঁততাৰ ওপৰত প্ৰভাৱ পেলায়।** স্পষ্ট কণ্ঠস্বৰ থকা উৎস অনুসৰণ কৰাটো সহজ; লাইভ ৰেকৰ্ডিং আৰু জোৰেৰে বেকিং ট্ৰেক থকা উৎসসমূহ স্পষ্টভাৱে কঠিন হয়।"
